/*
 * The script host's C layer over QuickJS. See include/jsp_script_host.h for the contract.
 *
 * Nothing here is global: every piece of state hangs off a jsh_engine, and QuickJS keeps its own
 * state in the engine's runtime, so engines on different threads never share memory.
 */
#include "jsp_script_host.h"

#include <math.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#if defined(__APPLE__)
#include <malloc/malloc.h>
#else
#include <malloc.h>
#endif

#include "quickjs.h"

/* Generated by scripts/build-native.mts from src/absentGlobals.ts. */
#include "jsh_absent_globals.h"

/* What QuickJS's own allocator counts for each block beyond its usable size. */
#define JSH_MALLOC_OVERHEAD 8

typedef struct {
	JSValue value;
	/* The next free slot's index while this one is free, -1 at the end of the list. */
	int32_t next_free;
	uint8_t used;
} jsh_slot;

struct jsh_engine {
	JSRuntime *rt;
	JSContext *ctx;
	jsh_host_fn host;
	uint8_t *buffer;
	int32_t capacity;

	jsh_slot *slots;
	int32_t slot_count;
	int32_t free_head;
	int32_t live;

	size_t memory_limit;
	double memory_used;

	double budget_callback;
	double budget_tick;
	double steps;
	double callback_steps;
	double tick_steps;
	double host_calls;
	double bytes_to_host;
	double bytes_from_host;
	double memory_limit_hits;

	/* How many entries from the host are running, counting the ones a host call made. */
	int depth;
	/* Set during the outermost entry when the budget or the memory limit stopped a script. */
	int terminated;
	int out_of_memory;
	/* Set while fail() describes an error, when a host call would overwrite the description. */
	int describing;
};

/* The steps a script's getters and conversions may take while fail() describes its error. */
#define JSH_DESCRIBE_STEPS 4
/* The bytes past the memory limit that describing an error may allocate. */
#define JSH_DESCRIBE_HEADROOM ((size_t)1 << 20)

/* ---------------------------------------------------------------- memory */

static size_t usable_size(const void *ptr) {
#if defined(__APPLE__)
	return malloc_size(ptr);
#elif defined(_WIN32)
	return _msize((void *)ptr);
#else
	return malloc_usable_size((void *)ptr);
#endif
}

static void refuse(JSMallocState *state) {
	jsh_engine *engine = state->opaque;
	engine->memory_limit_hits++;
	engine->out_of_memory = 1;
}

/* QuickJS's default allocator, with every refusal recorded on the engine. */
static void *engine_malloc(JSMallocState *state, size_t size) {
	if (state->malloc_size + size > state->malloc_limit) {
		refuse(state);
		return NULL;
	}
	void *ptr = malloc(size);
	if (!ptr) return NULL;
	size_t used = usable_size(ptr) + JSH_MALLOC_OVERHEAD;
	state->malloc_count++;
	state->malloc_size += used;
	((jsh_engine *)state->opaque)->memory_used += (double)used;
	return ptr;
}

static void engine_free(JSMallocState *state, void *ptr) {
	if (!ptr) return;
	size_t used = usable_size(ptr) + JSH_MALLOC_OVERHEAD;
	state->malloc_count--;
	state->malloc_size -= used;
	((jsh_engine *)state->opaque)->memory_used -= (double)used;
	free(ptr);
}

static void *engine_realloc(JSMallocState *state, void *ptr, size_t size) {
	if (!ptr) return size == 0 ? NULL : engine_malloc(state, size);
	if (size == 0) {
		engine_free(state, ptr);
		return NULL;
	}
	size_t old_size = usable_size(ptr);
	if (state->malloc_size + size - old_size > state->malloc_limit) {
		refuse(state);
		return NULL;
	}
	void *grown = realloc(ptr, size);
	if (!grown) return NULL;
	size_t new_size = usable_size(grown);
	state->malloc_size += new_size - old_size;
	((jsh_engine *)state->opaque)->memory_used += (double)new_size - (double)old_size;
	return grown;
}

static size_t engine_usable_size(const void *ptr) {
	return ptr ? usable_size(ptr) : 0;
}

static const JSMallocFunctions malloc_functions = {engine_malloc, engine_free, engine_realloc, engine_usable_size};

/* ---------------------------------------------------------------- handles */

static int32_t keep(jsh_engine *engine, JSValue value) {
	if (engine->free_head < 0) {
		int32_t count = engine->slot_count == 0 ? 64 : engine->slot_count * 2;
		jsh_slot *slots = realloc(engine->slots, sizeof(jsh_slot) * (size_t)count);
		if (!slots) {
			JS_FreeValue(engine->ctx, value);
			return JSH_OUT_OF_MEMORY;
		}
		for (int32_t i = count - 1; i >= engine->slot_count; i--) {
			slots[i].used = 0;
			slots[i].next_free = engine->free_head;
			engine->free_head = i;
		}
		engine->slots = slots;
		engine->slot_count = count;
	}
	int32_t index = engine->free_head;
	engine->free_head = engine->slots[index].next_free;
	engine->slots[index].value = value;
	engine->slots[index].used = 1;
	engine->live++;
	return index + 1;
}

static JSValue *lookup(jsh_engine *engine, int32_t handle) {
	if (handle < 1 || handle > engine->slot_count || !engine->slots[handle - 1].used) return NULL;
	return &engine->slots[handle - 1].value;
}

static void release(jsh_engine *engine, int32_t handle) {
	JSValue *value = lookup(engine, handle);
	if (!value) return;
	JS_FreeValue(engine->ctx, *value);
	jsh_slot *slot = &engine->slots[handle - 1];
	slot->used = 0;
	slot->next_free = engine->free_head;
	engine->free_head = handle - 1;
	engine->live--;
}

/* ---------------------------------------------------------------- transfer buffer */

/* Asks the host for a transfer buffer of at least `needed` bytes. */
static int reserve(jsh_engine *engine, int64_t needed) {
	if (needed <= engine->capacity) return 0;
	if (needed > INT32_MAX) return -1;
	if (engine->host(JSH_OP_GROW, 0, (int32_t)needed) != 0) return -1;
	return needed <= engine->capacity ? 0 : -1;
}

typedef struct {
	jsh_engine *engine;
	int32_t length;
	int failed;
	/* The handles this writer made, when it tracks them, so the caller can release them. */
	int32_t *made;
	int32_t made_count;
	int32_t made_capacity;
	int track;
} writer;

static void write_bytes(writer *out, const void *bytes, size_t size) {
	if (out->failed) return;
	if (reserve(out->engine, (int64_t)out->length + (int64_t)size) < 0) {
		out->failed = 1;
		return;
	}
	if (size > 0) memcpy(out->engine->buffer + out->length, bytes, size);
	out->length += (int32_t)size;
}

static void write_u8(writer *out, uint8_t value) {
	write_bytes(out, &value, 1);
}

static void write_u32(writer *out, uint32_t value) {
	uint8_t bytes[4] = {(uint8_t)value, (uint8_t)(value >> 8), (uint8_t)(value >> 16), (uint8_t)(value >> 24)};
	write_bytes(out, bytes, 4);
}

static void write_f64(writer *out, double value) {
	uint64_t bits;
	memcpy(&bits, &value, 8);
	uint8_t bytes[8];
	for (int i = 0; i < 8; i++) bytes[i] = (uint8_t)(bits >> (8 * i));
	write_bytes(out, bytes, 8);
}

static void write_string(writer *out, const char *text, size_t length) {
	write_u8(out, JSH_TAG_STRING);
	write_u32(out, (uint32_t)length);
	write_bytes(out, text, length);
}

/*
 * Writes one value. A value with no byte form is written as a handle: `existing` when the host
 * already holds one for it, otherwise a new handle the host must free.
 */
static void write_value(writer *out, JSValueConst value, int32_t existing) {
	JSContext *ctx = out->engine->ctx;
	switch (JS_VALUE_GET_TAG(value)) {
	case JS_TAG_UNDEFINED:
		write_u8(out, JSH_TAG_UNDEFINED);
		return;
	case JS_TAG_NULL:
		write_u8(out, JSH_TAG_NULL);
		return;
	case JS_TAG_BOOL:
		write_u8(out, JS_VALUE_GET_BOOL(value) ? JSH_TAG_TRUE : JSH_TAG_FALSE);
		return;
	case JS_TAG_INT:
		write_u8(out, JSH_TAG_NUMBER);
		write_f64(out, (double)JS_VALUE_GET_INT(value));
		return;
	case JS_TAG_FLOAT64:
		write_u8(out, JSH_TAG_NUMBER);
		write_f64(out, JS_VALUE_GET_FLOAT64(value));
		return;
	case JS_TAG_STRING:
	case JS_TAG_STRING_ROPE: {
		size_t length;
		const char *text = JS_ToCStringLen(ctx, &length, value);
		if (!text) {
			out->failed = 1;
			return;
		}
		write_string(out, text, length);
		JS_FreeCString(ctx, text);
		return;
	}
	default: {
		int32_t handle = existing > 0 ? existing : keep(out->engine, JS_DupValue(ctx, value));
		if (handle < 0) {
			out->failed = 1;
			return;
		}
		if (existing <= 0 && out->track) {
			if (out->made_count == out->made_capacity) {
				int32_t capacity = out->made_capacity == 0 ? 8 : out->made_capacity * 2;
				int32_t *made = realloc(out->made, sizeof(int32_t) * (size_t)capacity);
				if (!made) {
					release(out->engine, handle);
					out->failed = 1;
					return;
				}
				out->made = made;
				out->made_capacity = capacity;
			}
			out->made[out->made_count++] = handle;
		}
		write_u8(out, JSH_TAG_HANDLE);
		write_u32(out, (uint32_t)handle);
		return;
	}
	}
}

typedef struct {
	const uint8_t *bytes;
	int32_t length;
	int32_t position;
} reader;

static int read_u32(reader *in, uint32_t *value) {
	if (in->length - in->position < 4) return -1;
	const uint8_t *p = in->bytes + in->position;
	*value = (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
	in->position += 4;
	return 0;
}

/* Reads one string's bytes without copying them. */
static int read_string(reader *in, const char **text, uint32_t *length) {
	if (in->position >= in->length || in->bytes[in->position] != JSH_TAG_STRING) return -1;
	in->position++;
	if (read_u32(in, length) < 0 || (uint32_t)(in->length - in->position) < *length) return -1;
	*text = (const char *)in->bytes + in->position;
	in->position += (int32_t)*length;
	return 0;
}

/* Reads one value into a new reference. Returns -1 on a malformed value or a stale handle. */
static int read_value(jsh_engine *engine, reader *in, JSValue *value) {
	if (in->position >= in->length) return -1;
	uint8_t tag = in->bytes[in->position];
	switch (tag) {
	case JSH_TAG_UNDEFINED:
		in->position++;
		*value = JS_UNDEFINED;
		return 0;
	case JSH_TAG_NULL:
		in->position++;
		*value = JS_NULL;
		return 0;
	case JSH_TAG_FALSE:
	case JSH_TAG_TRUE:
		in->position++;
		*value = JS_NewBool(engine->ctx, tag == JSH_TAG_TRUE);
		return 0;
	case JSH_TAG_NUMBER: {
		if (in->length - in->position < 9) return -1;
		uint64_t bits = 0;
		for (int i = 0; i < 8; i++) bits |= (uint64_t)in->bytes[in->position + 1 + i] << (8 * i);
		double number;
		memcpy(&number, &bits, 8);
		in->position += 9;
		*value = JS_NewFloat64(engine->ctx, number);
		return 0;
	}
	case JSH_TAG_STRING: {
		const char *text;
		uint32_t length;
		if (read_string(in, &text, &length) < 0) return -1;
		*value = JS_NewStringLen(engine->ctx, text, length);
		return JS_IsException(*value) ? -1 : 0;
	}
	case JSH_TAG_HANDLE: {
		in->position++;
		uint32_t handle;
		if (read_u32(in, &handle) < 0) return -1;
		JSValue *held = lookup(engine, (int32_t)handle);
		if (!held) return -1;
		*value = JS_DupValue(engine->ctx, *held);
		return 0;
	}
	default:
		return -1;
	}
}

/* Reads a list of values into a new array of new references. */
static int read_list(jsh_engine *engine, reader *in, JSValue **values, int *count) {
	uint32_t length;
	if (read_u32(in, &length) < 0 || length > (uint32_t)(in->length - in->position)) return -1;
	JSValue *list = length == 0 ? NULL : malloc(sizeof(JSValue) * length);
	if (length > 0 && !list) return -1;
	for (uint32_t i = 0; i < length; i++) {
		if (read_value(engine, in, &list[i]) < 0) {
			for (uint32_t j = 0; j < i; j++) JS_FreeValue(engine->ctx, list[j]);
			free(list);
			return -1;
		}
	}
	*values = list;
	*count = (int)length;
	return 0;
}

static void free_list(jsh_engine *engine, JSValue *values, int count) {
	for (int i = 0; i < count; i++) JS_FreeValue(engine->ctx, values[i]);
	free(values);
}

/* ---------------------------------------------------------------- errors */

/* Throws the error the host described as two strings, a name and a message, in the buffer. */
static JSValue throw_host_error(jsh_engine *engine, int32_t length) {
	JSContext *ctx = engine->ctx;
	reader in = {engine->buffer, length < 0 ? engine->capacity : length, 0};
	const char *name, *message;
	uint32_t name_length, message_length;
	if (read_string(&in, &name, &name_length) < 0 || read_string(&in, &message, &message_length) < 0) {
		return JS_ThrowInternalError(ctx, "the host failed without describing the error");
	}
	JSValue error = JS_NewError(ctx);
	if (JS_IsException(error)) return error;
	JSValue text = JS_NewStringLen(ctx, message, message_length);
	JS_DefinePropertyValueStr(ctx, error, "message", text, JS_PROP_WRITABLE | JS_PROP_CONFIGURABLE);
	if (name_length > 0 && !(name_length == 5 && memcmp(name, "Error", 5) == 0)) {
		/* A standard error class gives the error its prototype, so instanceof works in script. */
		char class_name[32];
		JSValue prototype = JS_UNDEFINED;
		if (name_length < sizeof(class_name)) {
			memcpy(class_name, name, name_length);
			class_name[name_length] = 0;
			static const char *const classes[] = {"TypeError", "RangeError", "ReferenceError", "SyntaxError",
												  "InternalError", "EvalError", "URIError"};
			for (size_t i = 0; i < sizeof(classes) / sizeof(classes[0]); i++) {
				if (strcmp(class_name, classes[i]) != 0) continue;
				JSValue global = JS_GetGlobalObject(ctx);
				JSValue constructor = JS_GetPropertyStr(ctx, global, class_name);
				JS_FreeValue(ctx, global);
				if (JS_IsObject(constructor)) prototype = JS_GetPropertyStr(ctx, constructor, "prototype");
				JS_FreeValue(ctx, constructor);
				break;
			}
		}
		if (JS_IsObject(prototype)) {
			JS_SetPrototype(ctx, error, prototype);
		} else {
			JS_DefinePropertyValueStr(ctx, error, "name", JS_NewStringLen(ctx, name, name_length),
									  JS_PROP_WRITABLE | JS_PROP_CONFIGURABLE);
		}
		JS_FreeValue(ctx, prototype);
	}
	return JS_Throw(ctx, error);
}

/* Throws the engine's uncatchable termination error, as QuickJS's interrupt does. */
static JSValue throw_terminated(JSContext *ctx) {
	JS_ThrowInternalError(ctx, "interrupted");
	JS_SetUncatchableException(ctx, 1);
	return JS_EXCEPTION;
}

/* Converts a value to a string the caller frees with free(), or NULL when the conversion threw. */
static char *describe_value(JSContext *ctx, JSValueConst value) {
	size_t length;
	const char *text = JS_ToCStringLen(ctx, &length, value);
	if (!text) {
		JS_FreeValue(ctx, JS_GetException(ctx));
		return NULL;
	}
	char *copy = malloc(length + 1);
	if (copy) {
		memcpy(copy, text, length);
		copy[length] = 0;
	}
	JS_FreeCString(ctx, text);
	return copy;
}

static char *describe_property(JSContext *ctx, JSValueConst object, const char *key) {
	JSValue value = JS_GetPropertyStr(ctx, object, key);
	if (JS_IsException(value)) {
		JS_FreeValue(ctx, JS_GetException(ctx));
		return NULL;
	}
	char *text = JS_IsUndefined(value) ? NULL : describe_value(ctx, value);
	JS_FreeValue(ctx, value);
	return text;
}

static void write_description(writer *out, const char *name, const char *message, const char *stack) {
	write_string(out, name ? name : "", name ? strlen(name) : 0);
	write_string(out, message ? message : "", message ? strlen(message) : 0);
	write_string(out, stack ? stack : "", stack ? strlen(stack) : 0);
}

/*
 * Takes the pending exception, writes its name, message and stack, and returns the status.
 *
 * Reading them can run the script's own getters and toString, so describing gets a few steps and
 * a little memory of its own, past the budget and the limit that may have caused the error, and
 * no host calls. A getter that runs past them leaves its field empty.
 */
static int32_t fail(jsh_engine *engine) {
	JSContext *ctx = engine->ctx;
	int32_t status = engine->terminated ? JSH_TERMINATED : engine->out_of_memory ? JSH_OUT_OF_MEMORY : JSH_THROWN;
	JSValue exception = JS_GetException(ctx);
	int terminated = engine->terminated, out_of_memory = engine->out_of_memory;
	double budget_callback = engine->budget_callback, budget_tick = engine->budget_tick;
	engine->budget_callback = engine->callback_steps + JSH_DESCRIBE_STEPS;
	engine->budget_tick = engine->tick_steps + JSH_DESCRIBE_STEPS;
	if (engine->memory_limit > 0) JS_SetMemoryLimit(engine->rt, engine->memory_limit + JSH_DESCRIBE_HEADROOM);
	engine->describing = 1;

	/* Every field is read before any is written, so nothing the reads run can reach the buffer. */
	char *name = NULL, *message = NULL, *stack = NULL;
	if (JS_IsError(ctx, exception)) {
		name = describe_property(ctx, exception, "name");
		message = describe_property(ctx, exception, "message");
		stack = describe_property(ctx, exception, "stack");
	} else {
		message = describe_value(ctx, exception);
	}
	JS_FreeValue(ctx, exception);

	engine->describing = 0;
	engine->terminated = terminated;
	engine->out_of_memory = out_of_memory;
	engine->budget_callback = budget_callback;
	engine->budget_tick = budget_tick;
	JS_SetMemoryLimit(engine->rt, engine->memory_limit > 0 ? engine->memory_limit : (size_t)-1);

	writer out = {engine, 0, 0, NULL, 0, 0, 0};
	write_description(&out, name, message, stack);
	free(name);
	free(message);
	free(stack);
	return status;
}

/* ---------------------------------------------------------------- entries */

static void enter(jsh_engine *engine) {
	if (engine->depth++ > 0) return;
	/* The host may call from any depth of its own stack, so the stack limit starts here. */
	JS_UpdateStackTop(engine->rt);
	/* Each entry counts its steps from a full poll counter, so what ran before cannot move them. */
	JS_ResetInterruptCounter(engine->ctx);
	engine->callback_steps = 0;
	engine->terminated = 0;
	engine->out_of_memory = 0;
}

static void leave(jsh_engine *engine) {
	engine->depth--;
}

/* Keeps a result, or reports the pending exception when there is none. */
static int32_t settle(jsh_engine *engine, JSValue value) {
	if (JS_IsException(value)) return fail(engine);
	return keep(engine, value);
}

static int interrupt(JSRuntime *rt, void *opaque) {
	(void)rt;
	jsh_engine *engine = opaque;
	engine->steps++;
	engine->callback_steps++;
	engine->tick_steps++;
	if (engine->callback_steps > engine->budget_callback || engine->tick_steps > engine->budget_tick) {
		engine->terminated = 1;
		return 1;
	}
	return 0;
}

static JSValue host_call(JSContext *ctx, JSValueConst this_value, int argc, JSValueConst *argv, int id) {
	(void)this_value;
	jsh_engine *engine = JS_GetContextOpaque(ctx);
	/* The host's answer would overwrite the error description being collected. */
	if (engine->describing) return JS_ThrowInternalError(ctx, "the host cannot be called while an error is described");
	writer out = {engine, 0, 0, NULL, 0, 0, 1};
	write_u32(&out, (uint32_t)argc);
	for (int i = 0; i < argc; i++) write_value(&out, argv[i], 0);
	JSValue result;
	if (out.failed) {
		result = JS_ThrowInternalError(ctx, "the arguments do not fit the host's buffer");
		goto done;
	}

	engine->host_calls++;
	engine->bytes_to_host += out.length;
	int32_t length = engine->host(JSH_OP_CALL, id, out.length);
	if (engine->terminated) {
		/* A script the host ran in the meantime used up the budget, so this one stops too. */
		result = throw_terminated(ctx);
	} else if (length == -1) {
		result = throw_host_error(engine, -1);
	} else if (length < 0 || length > engine->capacity) {
		result = JS_ThrowInternalError(ctx, "the host returned no result");
	} else {
		engine->bytes_from_host += length;
		reader in = {engine->buffer, length, 0};
		int read = read_value(engine, &in, &result) == 0;
		if (read && in.position != length) {
			JS_FreeValue(ctx, result);
			read = 0;
		}
		if (!read) result = JS_ThrowInternalError(ctx, "the host returned a malformed result");
	}
done:
	/* The argument handles last for the call; a host that keeps one has duplicated it. */
	for (int32_t i = 0; i < out.made_count; i++) release(engine, out.made[i]);
	free(out.made);
	return result;
}

static JSModuleDef *load_module(JSContext *ctx, const char *name, void *opaque) {
	jsh_engine *engine = opaque;
	size_t name_length = strlen(name);
	if (reserve(engine, (int64_t)name_length) < 0) {
		JS_ThrowInternalError(ctx, "the module name does not fit the host's buffer");
		return NULL;
	}
	memcpy(engine->buffer, name, name_length);
	int32_t length = engine->host(JSH_OP_LOAD_MODULE, 0, (int32_t)name_length);
	if (length == -1) {
		throw_host_error(engine, -1);
		return NULL;
	}
	if (length < 0 || length > engine->capacity) {
		JS_ThrowInternalError(ctx, "the host returned no source for module '%s'", name);
		return NULL;
	}
	engine->bytes_from_host += length;

	/* QuickJS reads one byte past the source, and compiling may load modules into the buffer. */
	char *source = malloc((size_t)length + 1);
	if (!source) {
		JS_ThrowOutOfMemory(ctx);
		return NULL;
	}
	memcpy(source, engine->buffer, (size_t)length);
	source[length] = 0;
	JSValue compiled = JS_Eval(ctx, source, (size_t)length, name, JS_EVAL_TYPE_MODULE | JS_EVAL_FLAG_COMPILE_ONLY);
	free(source);
	if (JS_IsException(compiled)) return NULL;
	JSModuleDef *module = JS_VALUE_GET_PTR(compiled);
	JS_FreeValue(ctx, compiled);
	return module;
}

/* The atom of the well-known symbol Symbol[name], or JS_ATOM_NULL when there is none. */
static JSAtom well_known_symbol(JSContext *ctx, JSValueConst global, const char *name) {
	JSValue constructor = JS_GetPropertyStr(ctx, global, "Symbol");
	JSValue symbol = JS_GetPropertyStr(ctx, constructor, name);
	JS_FreeValue(ctx, constructor);
	JSAtom atom = JS_IsSymbol(symbol) ? JS_ValueToAtom(ctx, symbol) : JS_ATOM_NULL;
	JS_FreeValue(ctx, symbol);
	return atom;
}

/* Deletes every path in the absent list, members first, since a member can hang off a global. */
static void remove_absent(JSContext *ctx) {
	JSValue global = JS_GetGlobalObject(ctx);
	for (int pass = 0; pass < 2; pass++) {
		for (size_t i = 0; i < sizeof(jsh_absent_globals) / sizeof(jsh_absent_globals[0]); i++) {
			const jsh_absent_path *path = &jsh_absent_globals[i];
			if ((pass == 0) != (path->owner[0] != '\0')) continue;

			JSValue object = JS_DupValue(ctx, global);
			for (const char *segment = path->owner; *segment && JS_IsObject(object);) {
				const char *dot = strchr(segment, '.');
				size_t length = dot ? (size_t)(dot - segment) : strlen(segment);
				JSAtom atom = JS_NewAtomLen(ctx, segment, length);
				JSValue next = JS_GetProperty(ctx, object, atom);
				JS_FreeAtom(ctx, atom);
				JS_FreeValue(ctx, object);
				object = next;
				segment += dot ? length + 1 : length;
			}
			if (JS_IsObject(object)) {
				JSAtom atom = path->symbol ? well_known_symbol(ctx, global, path->key) : JS_NewAtom(ctx, path->key);
				if (atom != JS_ATOM_NULL) {
					JS_DeleteProperty(ctx, object, atom, 0);
					JS_FreeAtom(ctx, atom);
				}
			}
			JS_FreeValue(ctx, object);
		}
	}
	JS_FreeValue(ctx, global);
}

/* ---------------------------------------------------------------- interface */

int32_t jsh_abi_version(void) {
	return JSH_ABI_VERSION;
}

jsh_engine *jsh_engine_create(jsh_host_fn host, uint8_t *buffer, int32_t capacity, double memory_limit,
							  double stack_size) {
	if (!host || !buffer || capacity < 64) return NULL;
	jsh_engine *engine = calloc(1, sizeof(jsh_engine));
	if (!engine) return NULL;
	engine->host = host;
	engine->buffer = buffer;
	engine->capacity = capacity;
	engine->free_head = -1;
	engine->budget_callback = INFINITY;
	engine->budget_tick = INFINITY;
	engine->memory_limit = memory_limit > 0 ? (size_t)memory_limit : 0;

	engine->rt = JS_NewRuntime2(&malloc_functions, engine);
	if (!engine->rt) {
		free(engine);
		return NULL;
	}
	JS_SetRuntimeOpaque(engine->rt, engine);
	if (stack_size > 0) JS_SetMaxStackSize(engine->rt, (size_t)stack_size);
	JS_SetInterruptHandler(engine->rt, interrupt, engine);
	JS_SetModuleLoaderFunc(engine->rt, NULL, load_module, engine);

	engine->ctx = JS_NewContext(engine->rt);
	if (!engine->ctx) {
		JS_FreeRuntime(engine->rt);
		free(engine);
		return NULL;
	}
	JS_SetContextOpaque(engine->ctx, engine);
	JS_DisableFunctionFromString(engine->ctx);
	JS_DisableNewRegExpSyntax(engine->ctx);
	if (JS_AddLegacyMembers(engine->ctx) < 0) {
		JS_FreeContext(engine->ctx);
		JS_FreeRuntime(engine->rt);
		free(engine);
		return NULL;
	}
	remove_absent(engine->ctx);
	/* The limit applies to scripts, not to the context's own objects. */
	if (engine->memory_limit > 0) JS_SetMemoryLimit(engine->rt, engine->memory_limit);
	return engine;
}

void jsh_engine_destroy(jsh_engine *engine) {
	if (!engine || engine->depth > 0) return;
	for (int32_t i = 0; i < engine->slot_count; i++) {
		if (engine->slots[i].used) JS_FreeValue(engine->ctx, engine->slots[i].value);
	}
	free(engine->slots);
	JS_FreeContext(engine->ctx);
	JS_FreeRuntime(engine->rt);
	free(engine);
}

void jsh_engine_set_buffer(jsh_engine *engine, uint8_t *buffer, int32_t capacity) {
	if (!engine || !buffer || capacity < 64) return;
	engine->buffer = buffer;
	engine->capacity = capacity;
}

void jsh_engine_set_budget(jsh_engine *engine, double per_callback, double per_tick) {
	if (!engine) return;
	engine->budget_callback = per_callback > 0 ? per_callback : INFINITY;
	engine->budget_tick = per_tick > 0 ? per_tick : INFINITY;
}

void jsh_engine_begin_tick(jsh_engine *engine) {
	if (engine) engine->tick_steps = 0;
}

double jsh_engine_stat(jsh_engine *engine, int32_t stat) {
	if (!engine) return NAN;
	switch (stat) {
	case JSH_STAT_STEPS:
		return engine->steps;
	case JSH_STAT_CALLBACK_STEPS:
		return engine->callback_steps;
	case JSH_STAT_TICK_STEPS:
		return engine->tick_steps;
	case JSH_STAT_HOST_CALLS:
		return engine->host_calls;
	case JSH_STAT_BYTES_TO_HOST:
		return engine->bytes_to_host;
	case JSH_STAT_BYTES_FROM_HOST:
		return engine->bytes_from_host;
	case JSH_STAT_STACK_OVERFLOWS:
		return (double)JS_GetStackOverflowCount(engine->rt);
	case JSH_STAT_MEMORY_LIMIT_HITS:
		return engine->memory_limit_hits;
	case JSH_STAT_MEMORY_USED:
		return engine->memory_used;
	case JSH_STAT_HANDLES:
		return engine->live;
	default:
		return NAN;
	}
}

int32_t jsh_eval_script(jsh_engine *engine, const char *name, const uint8_t *source, int32_t length) {
	if (!engine || !name || !source || length < 0) return JSH_INVALID;
	enter(engine);
	int32_t result = settle(engine, JS_Eval(engine->ctx, (const char *)source, (size_t)length, name, JS_EVAL_TYPE_GLOBAL));
	leave(engine);
	return result;
}

int32_t jsh_eval_module(jsh_engine *engine, const char *name, const uint8_t *source, int32_t length) {
	if (!engine || !name || !source || length < 0) return JSH_INVALID;
	JSContext *ctx = engine->ctx;
	enter(engine);
	int32_t result;
	JSValue compiled =
		JS_Eval(ctx, (const char *)source, (size_t)length, name, JS_EVAL_TYPE_MODULE | JS_EVAL_FLAG_COMPILE_ONLY);
	if (JS_IsException(compiled)) {
		result = fail(engine);
	} else {
		JSModuleDef *module = JS_VALUE_GET_PTR(compiled);
		JSValue promise = JS_EvalFunction(ctx, compiled);
		if (JS_IsException(promise)) {
			result = fail(engine);
		} else if (JS_PromiseState(ctx, promise) == JS_PROMISE_REJECTED) {
			JS_Throw(ctx, JS_PromiseResult(ctx, promise));
			JS_FreeValue(ctx, promise);
			result = fail(engine);
		} else {
			JS_FreeValue(ctx, promise);
			result = settle(engine, JS_GetModuleNamespace(ctx, module));
		}
	}
	leave(engine);
	return result;
}

int32_t jsh_run_jobs(jsh_engine *engine) {
	if (!engine) return JSH_INVALID;
	enter(engine);
	int32_t count = 0;
	for (;;) {
		JSContext *job_context;
		int ran = JS_ExecutePendingJob(engine->rt, &job_context);
		if (ran == 0) break;
		if (ran < 0) {
			count = fail(engine);
			break;
		}
		if (engine->terminated) {
			/*
			 * A promise reaction takes the termination into its promise's rejection, so the job
			 * reports success. The script is stopped all the same, and the host is told so.
			 */
			writer out = {engine, 0, 0, NULL, 0, 0, 0};
			write_description(&out, "InternalError", "interrupted", NULL);
			count = JSH_TERMINATED;
			break;
		}
		count++;
	}
	leave(engine);
	return count;
}

int32_t jsh_call(jsh_engine *engine, int32_t function, int32_t this_value, int32_t length) {
	if (!engine || length < 0 || length > engine->capacity) return JSH_INVALID;
	JSValue *callee = lookup(engine, function);
	JSValue *receiver = this_value == 0 ? NULL : lookup(engine, this_value);
	if (!callee || (this_value != 0 && !receiver)) return JSH_INVALID;
	/* The arguments leave the buffer before the call, which may reuse it. */
	reader in = {engine->buffer, length, 0};
	JSValue *arguments;
	int count;
	if (read_list(engine, &in, &arguments, &count) < 0) return JSH_INVALID;
	if (in.position != length) {
		free_list(engine, arguments, count);
		return JSH_INVALID;
	}
	JSValue function_value = JS_DupValue(engine->ctx, *callee);
	JSValue receiver_value = receiver ? JS_DupValue(engine->ctx, *receiver) : JS_UNDEFINED;
	enter(engine);
	int32_t result = settle(engine, JS_Call(engine->ctx, function_value, receiver_value, count, arguments));
	leave(engine);
	JS_FreeValue(engine->ctx, function_value);
	JS_FreeValue(engine->ctx, receiver_value);
	free_list(engine, arguments, count);
	return result;
}

int32_t jsh_global(jsh_engine *engine) {
	if (!engine) return JSH_INVALID;
	return keep(engine, JS_GetGlobalObject(engine->ctx));
}

int32_t jsh_get(jsh_engine *engine, int32_t object, const char *key) {
	JSValue *held = engine ? lookup(engine, object) : NULL;
	if (!held || !key) return JSH_INVALID;
	JSValue target = JS_DupValue(engine->ctx, *held);
	enter(engine);
	int32_t result = settle(engine, JS_GetPropertyStr(engine->ctx, target, key));
	leave(engine);
	JS_FreeValue(engine->ctx, target);
	return result;
}

int32_t jsh_set(jsh_engine *engine, int32_t object, const char *key, int32_t value) {
	JSValue *held = engine ? lookup(engine, object) : NULL;
	JSValue *assigned = engine ? lookup(engine, value) : NULL;
	if (!held || !assigned || !key) return JSH_INVALID;
	JSValue target = JS_DupValue(engine->ctx, *held);
	enter(engine);
	int32_t result = JS_SetPropertyStr(engine->ctx, target, key, JS_DupValue(engine->ctx, *assigned)) < 0 ? fail(engine) : 0;
	leave(engine);
	JS_FreeValue(engine->ctx, target);
	return result;
}

int32_t jsh_host_function(jsh_engine *engine, int32_t id, const char *name, int32_t length) {
	if (!engine || !name || length < 0) return JSH_INVALID;
	JSValue function = JS_NewCFunctionMagic(engine->ctx, host_call, name, length, JS_CFUNC_generic_magic, id);
	if (JS_IsException(function)) return fail(engine);
	return keep(engine, function);
}

int32_t jsh_decode(jsh_engine *engine, int32_t length) {
	if (!engine || length < 0 || length > engine->capacity) return JSH_INVALID;
	reader in = {engine->buffer, length, 0};
	JSValue value;
	if (read_value(engine, &in, &value) < 0) {
		if (JS_HasException(engine->ctx)) JS_FreeValue(engine->ctx, JS_GetException(engine->ctx));
		return JSH_INVALID;
	}
	if (in.position != length) {
		JS_FreeValue(engine->ctx, value);
		return JSH_INVALID;
	}
	return keep(engine, value);
}

int32_t jsh_encode(jsh_engine *engine, int32_t handle) {
	JSValue *held = engine ? lookup(engine, handle) : NULL;
	if (!held) return JSH_INVALID;
	writer out = {engine, 0, 0, NULL, 0, 0, 0};
	write_value(&out, *held, handle);
	if (out.failed) {
		if (JS_HasException(engine->ctx)) JS_FreeValue(engine->ctx, JS_GetException(engine->ctx));
		return JSH_OUT_OF_MEMORY;
	}
	return out.length;
}

int32_t jsh_dup(jsh_engine *engine, int32_t handle) {
	JSValue *held = engine ? lookup(engine, handle) : NULL;
	if (!held) return JSH_INVALID;
	return keep(engine, JS_DupValue(engine->ctx, *held));
}

void jsh_free(jsh_engine *engine, int32_t handle) {
	if (engine) release(engine, handle);
}
